from __future__ import print_function
from __future__ import unicode_literals

import argparse
import sys


FIXES = {
    'auto': lambda lines: normalize_auto(lines),
    'no': lambda lines: lines,
    'cr': lambda lines: fix_to_cr(lines),
    'crlf': lambda lines: fix_to_crlf(lines),
    'lf': lambda lines: fix_to_lf(lines),
}


def normalize_auto(lines):
    """Detect predominant line ending and normalize all lines to it."""
    cr_count = sum(1 for line in lines if line.endswith(b'\r') and not line.endswith(b'\r\n'))
    crlf_count = sum(1 for line in lines if line.endswith(b'\r\n'))
    lf_count = sum(1 for line in lines if line.endswith(b'\n') and not line.endswith(b'\r\n'))

    total = cr_count + crlf_count + lf_count
    if total == 0:
        return lines

    if crlf_count >= cr_count and crlf_count >= lf_count:
        return fix_to_crlf(lines)
    elif lf_count >= cr_count and lf_count >= crlf_count:
        return fix_to_lf(lines)
    else:
        return fix_to_cr(lines)


def fix_to_cr(lines):
    return [line.rstrip(b'\r\n') + b'\r' for line in lines]


def fix_to_crlf(lines):
    return [line.rstrip(b'\r\n') + b'\r\n' for line in lines]


def fix_to_lf(lines):
    return [line.rstrip(b'\r\n') + b'\n' for line in lines]


def has_mixed_line_endings(lines):
    """Check if lines have mixed line endings."""
    endings = set()
    for line in lines:
        if line.endswith(b'\r\n'):
            endings.add('crlf')
        elif line.endswith(b'\r'):
            endings.add('cr')
        elif line.endswith(b'\n'):
            endings.add('lf')
    return len(endings) > 1


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument('-f', '--fix', choices=['auto', 'no', 'cr', 'crlf', 'lf'], default='auto')
    parser.add_argument('filenames', nargs='+')
    args = parser.parse_args(argv)

    fix_func = FIXES[args.fix]
    retv = 0

    for filename in args.filenames:
        with open(filename, 'rb') as f:
            content = f.read()

        if not content:
            continue

        lines = content.split(b'\n')
        # Rejoin to handle \r\n properly
        lines = [line + b'\n' if i < len(lines) - 1 else line for i, line in enumerate(content.split(b'\n'))]

        if has_mixed_line_endings(lines):
            fixed = fix_func(lines)
            with open(filename, 'wb') as f:
                f.write(b''.join(fixed))
            print('Fixed {}'.format(filename))
            retv = 1

    return retv


if __name__ == '__main__':
