   216	func hashFile(fn string) (string, error) {
   217		f, err := os.Open(fn)
   218		if err != nil {
   219			return "", fmt.Errorf("can't open input file: %v", err)
   220		}
   221		defer f.Close()
   222	
   223		h := sha1.New()
   224		if _, err := io.Copy(h, f); err != nil {
   225			return "", fmt.Errorf("can't write data to hash: %v", err)
   226		}
   227		return fmt.Sprintf("%x", h.Sum(nil)), nil
   228	}
