// Run runs the BackendHandler workers until the Context is closed.
func (bh *BackendHandler) Run(ctx context.Context) {
	var wg wait.Group
	for _, worker := range bh.workers {
		wg.Start(worker.work)
	}

	// Work until asked to stop
	<-ctx.Done()

	// Close the channels to signal workers to stop.
	// Workers will continue to process any remaining items in the channel buffer
	// before exiting (they check the ok flag after reading from the channel).
	for _, worker := range bh.workers {
		close(worker.metricsQueue)
		close(worker.metricMapQueue)
	}

	// Wait for all workers to finish processing
	wg.Wait()
}

